create extension if not exists "pgcrypto";
create type public.membership_status as enum ('pending','active','expired','suspended','rejected');
create type public.return_status as enum ('planning','returned');
create type public.user_role as enum ('member','staff','admin');
create table public.membership_applications (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),full_name text not null,email text not null,phone text not null,current_country text not null,return_status public.return_status not null,return_date date,district text,professional_background text,skills text,support_needs text not null,consent text not null default 'yes',consented_at timestamptz not null default now(),status public.membership_status not null default 'pending');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),full_name text not null,phone text,role public.user_role not null default 'member',current_country text,return_status public.return_status,return_date date,district text,professional_background text,skills text,business_interests text,investment_interests text,support_needs text,membership_status public.membership_status not null default 'pending',membership_expires_at timestamptz);
create table public.support_requests (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),member_id uuid references public.profiles(id) on delete set null,category text not null,subject text not null,details text not null,status text not null default 'open',assigned_to uuid references public.profiles(id) on delete set null);
create table public.opportunities (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),title text not null,category text not null,summary text not null,source_url text,expires_at timestamptz,published boolean not null default false);
alter table public.membership_applications enable row level security;alter table public.profiles enable row level security;alter table public.support_requests enable row level security;alter table public.opportunities enable row level security;
create policy "members read own profile" on public.profiles for select using (auth.uid() = id);create policy "members update own profile" on public.profiles for update using (auth.uid() = id);create policy "members read own support" on public.support_requests for select using (auth.uid() = member_id);create policy "members create own support" on public.support_requests for insert with check (auth.uid() = member_id);create policy "public read published opportunities" on public.opportunities for select using (published = true);
